package main

import (
	"fmt"
	"os"
	"time"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/palos/pash/internal/status"

	"github.com/spf13/cobra"
)

var rootCmd = &cobra.Command{
	Use:   "pash",
	Short: "PalOS Agentic Shell",
	Run: func(cmd *cobra.Command, args []string) {
		p := tea.NewProgram(initialModel())
		if _, err := p.Run(); err != nil {
			fmt.Printf("Error: %v", err)
			os.Exit(1)
		}
	},
}

func main() {
	if err := rootCmd.Execute(); err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

type model struct {
	services []status.Service
	quitting bool
}

type tickMsg time.Time

func initialModel() model {
	return model{
		services: status.CheckAll(),
	}
}

func (m model) Init() tea.Cmd {
	return tea.Tick(time.Second, func(t time.Time) tea.Msg {
		return tickMsg(t)
	})
}

func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		if msg.String() == "q" || msg.String() == "ctrl+c" {
			m.quitting = true
			return m, tea.Quit
		}
	case tickMsg:
		m.services = status.CheckAll()
		return m, tea.Tick(time.Second, func(t time.Time) tea.Msg {
			return tickMsg(t)
		})
	}
	return m, nil
}

func (m model) View() string {
	if m.quitting {
		return "Bye!\n"
	}

	// Styles
	titleStyle := lipgloss.NewStyle().
		Bold(true).
		Foreground(lipgloss.Color("#FAFAFA")).
		Background(lipgloss.Color("#7D56F4")).
		Padding(0, 1).
		MarginBottom(1)

	rowStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("252"))

	// Header
	s := titleStyle.Render("PalOS Brain Monitor") + "\n\n"

	// Table
	for _, svc := range m.services {
		s += rowStyle.Render(fmt.Sprintf("%-15s %-10s %s", svc.Name, svc.Port, svc.Status)) + "\n"
	}

	s += "\nPress 'q' to quit."
	return s
}

package main

import (
	"fmt"
	"log"
	"net/http"
	"os/exec"

	"github.com/creack/pty"
	"github.com/gorilla/websocket"
	"github.com/palos/pash/rpc"
	"github.com/spf13/cobra"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func init() {
	var daemonCmd = &cobra.Command{
		Use:   "daemon",
		Short: "Start the PalOS Backend Server",
		Run: func(cmd *cobra.Command, args []string) {
			startServer()
		},
	}
	rootCmd.AddCommand(daemonCmd)
}

func startServer() {
	http.HandleFunc("/ws/shell", handlePty)
	http.HandleFunc("/ws/control", rpc.HandleControl)
	fmt.Println("Pash Daemon listening on :8081 🚀")
	log.Fatal(http.ListenAndServe(":8081", nil))
}

func handlePty(w http.ResponseWriter, r *http.Request) {
	c, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Print("upgrade:", err)
		return
	}
	defer c.Close()

	// Start a shell
	cmd := exec.Command("/bin/zsh")
	ptmx, err := pty.Start(cmd)
	if err != nil {
		log.Print("pty:", err)
		return
	}
	defer func() { _ = ptmx.Close() }()

	// Pipe PTY -> WebSocket
	go func() {
		buf := make([]byte, 1024)
		for {
			n, err := ptmx.Read(buf)
			if err != nil {
				return
			}
			if err := c.WriteMessage(websocket.BinaryMessage, buf[:n]); err != nil {
				return
			}
		}
	}()

	// Pipe WebSocket -> PTY
	for {
		_, message, err := c.ReadMessage()
		if err != nil {
			return
		}
		if _, err := ptmx.Write(message); err != nil {
			return
		}
	}
}

import { WebTerminal as Terminal } from './components/Terminal';
import { Chat } from './components/Chat';
import { WebSocketProvider } from './context/WebSocketContext';

