package rpc

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os/exec"

	"github.com/gorilla/websocket"
)

type Request struct {
	JSONRPC string          `json:"jsonrpc"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params"`
	ID      interface{}     `json:"id"`
}

type Response struct {
	JSONRPC string      `json:"jsonrpc"`
	Result  interface{} `json:"result,omitempty"`
	Error   *RPCError   `json:"error,omitempty"`
	ID      interface{} `json:"id"`
}

type RPCError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

func HandleControl(w http.ResponseWriter, r *http.Request) {
	c, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Print("upgrade:", err)
		return
	}
	defer c.Close()

	for {
		mt, message, err := c.ReadMessage()
		if err != nil {
			break
		}
		if mt != websocket.TextMessage {
			continue
		}

		var req Request
		if err := json.Unmarshal(message, &req); err != nil {
			sendError(c, nil, -32700, "Parse error")
			continue
		}

		go func(req Request) {
			res := processRequest(req)
			if err := c.WriteJSON(res); err != nil {
				log.Println("write:", err)
			}
		}(req)
	}
}

func processRequest(req Request) Response {
	var result interface{}
	var err error

	switch req.Method {
	case "fs.list":
		var params struct {
			Path string `json:"path"`
		}
		if json.Unmarshal(req.Params, &params) == nil {
			result, err = listDir(params.Path)
		} else {
			return errorResponse(req.ID, -32602, "Invalid params")
		}
	case "fs.read":
		var params struct {
			Path string `json:"path"`
		}
		if json.Unmarshal(req.Params, &params) == nil {
			result, err = readFile(params.Path)
		} else {
			return errorResponse(req.ID, -32602, "Invalid params")
		}
	case "cmd.run":
		var params struct {
			Command string   `json:"command"`
			Args    []string `json:"args"`
			Dir     string   `json:"dir"`
		}
		if json.Unmarshal(req.Params, &params) == nil {
			result, err = runCommand(params.Command, params.Args, params.Dir)
		} else {
			return errorResponse(req.ID, -32602, "Invalid params")
		}
	default:
		return errorResponse(req.ID, -32601, "Method not found")
	}

	if err != nil {
		return errorResponse(req.ID, -32000, err.Error())
	}

	return Response{
		JSONRPC: "2.0",
		Result:  result,
		ID:      req.ID,
	}
}

func sendError(c *websocket.Conn, id interface{}, code int, msg string) {
	c.WriteJSON(errorResponse(id, code, msg))
}

func errorResponse(id interface{}, code int, msg string) Response {
	return Response{
		JSONRPC: "2.0",
		Error:   &RPCError{Code: code, Message: msg},
		ID:      id,
	}
}

// --- Implementations ---

func listDir(path string) ([]string, error) {
	if path == "" {
		path = "."
	}
	files, err := ioutil.ReadDir(path)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, f := range files {
		names = append(names, f.Name())
	}
	return names, nil
}

func readFile(path string) (string, error) {
	content, err := ioutil.ReadFile(path)
	if err != nil {
		return "", err
	}
	return string(content), nil
}

func runCommand(command string, args []string, dir string) (string, error) {
	cmd := exec.Command(command, args...)
	if dir != "" {
		cmd.Dir = dir
	}
	out, err := cmd.CombinedOutput()
	if err != nil {
		return string(out), fmt.Errorf("command failed: %v\noutput: %s", err, string(out))
	}
	return string(out), nil
}

package config

import (
	"os"

	"github.com/joho/godotenv"
)

type Config struct {
	OpenAIKey string
	Port      string
}

func Load() *Config {
	// Load .env from project root (one level up from pash/ or two levels if running from pash binary)
	// For simplicity in MVP, we try loading from current directory or parent
	_ = godotenv.Load(".env")
	_ = godotenv.Load("../.env")

	return &Config{
		OpenAIKey: os.Getenv("OPENAI_API_KEY"),
		Port:      getEnv("PORT", "8081"),
	}
}

func getEnv(key, fallback string) string {
	if value, exists := os.LookupEnv(key); exists {
		return value
	}
	return fallback
}

package status

import (
	"net"
	"time"
)

type Service struct {
	Name   string
	Port   string
	Status string // "🟢 Online" | "🔴 Offline"
}

func Check(name, port string) Service {
	timeout := 500 * time.Millisecond
	conn, err := net.DialTimeout("tcp", "localhost:"+port, timeout)
	status := "🔴 Offline"
	if err == nil {
		status = "🟢 Online"
		conn.Close()
	}
	return Service{Name: name, Port: port, Status: status}
}

func CheckAll() []Service {
	return []Service{
		Check("Postgres", "5432"),
		Check("MinIO", "9002"),
		Check("Authelia", "9091"),
		Check("Glances", "61208"),
		Check("Dozzle", "8080"),
	}
}
